def parse_rows(text):
    result={}
    for index,line in enumerate((x for x in text.splitlines() if x.strip()),1):
        fields=tuple(v.strip() for v in line.split("|"))
        if len(fields)!=9:raise ValueError(f"Year4 {index} expected 9 activity fields")
        sp=fields[0]
        if sp in result or any(not x for x in fields):raise ValueError("Bad row "+sp)
        result[sp]=dict(zip(_FIELDS[1:],fields[1:]))
    return result

BANK=parse_rows(_ROWS)
if len(BANK)!=79:
    raise RuntimeError(f"Expected 79 unique Year4 SP, got {len(BANK)}")
